import{_ as a,o as t,c as s,a2 as r}from"./chunks/framework.D7WGirly.js";const p=JSON.parse('{"title":"Releases — Troubleshooting & FAQs","description":"","frontmatter":{},"headers":[],"relativePath":"releases-04-troubleshooting-and-faqs.md","filePath":"releases-04-troubleshooting-and-faqs.md"}'),o={name:"releases-04-troubleshooting-and-faqs.md"};function n(i,e,l,h,d,c){return t(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="releases-—-troubleshooting-faqs" tabindex="-1">Releases — Troubleshooting &amp; FAQs <a class="header-anchor" href="#releases-—-troubleshooting-faqs" aria-label="Permalink to &quot;Releases — Troubleshooting &amp; FAQs&quot;">​</a></h1><p><em>Common issues, edge cases, and answers to frequent questions</em></p><hr><h2 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h2><h3 id="who-can-create-a-release" tabindex="-1">Who can create a Release? <a class="header-anchor" href="#who-can-create-a-release" aria-label="Permalink to &quot;Who can create a Release?&quot;">​</a></h3><p>Any workspace member can create a Release — it is not restricted to admins.</p><h3 id="can-a-workspace-have-multiple-releases" tabindex="-1">Can a workspace have multiple Releases? <a class="header-anchor" href="#can-a-workspace-have-multiple-releases" aria-label="Permalink to &quot;Can a workspace have multiple Releases?&quot;">​</a></h3><p>Yes. There is no limit on simultaneous Releases. A workspace commonly has several active at once — for example, a quarterly release, an ongoing backlog view, and a milestone-specific release.</p><h3 id="can-the-same-feature-appear-in-more-than-one-release" tabindex="-1">Can the same Feature appear in more than one Release? <a class="header-anchor" href="#can-the-same-feature-appear-in-more-than-one-release" aria-label="Permalink to &quot;Can the same Feature appear in more than one Release?&quot;">​</a></h3><p>Yes. Features can belong to multiple Releases simultaneously, and their status is consistent across all of them. A status update in one Release updates the Feature everywhere.</p><h3 id="can-i-remove-a-feature-from-a-release-without-deleting-it" tabindex="-1">Can I remove a Feature from a Release without deleting it? <a class="header-anchor" href="#can-i-remove-a-feature-from-a-release-without-deleting-it" aria-label="Permalink to &quot;Can I remove a Feature from a Release without deleting it?&quot;">​</a></h3><p>Yes. Removing a Feature from a Release only removes it from that Release board — the Feature remains in the backlog and any other Releases it belongs to.</p><h3 id="can-i-rename-a-release-after-creating-it" tabindex="-1">Can I rename a Release after creating it? <a class="header-anchor" href="#can-i-rename-a-release-after-creating-it" aria-label="Permalink to &quot;Can I rename a Release after creating it?&quot;">​</a></h3><p>Yes. Release names can be edited at any time.</p><h3 id="does-forecast-mode-affect-real-feature-status" tabindex="-1">Does Forecast mode affect real Feature status? <a class="header-anchor" href="#does-forecast-mode-affect-real-feature-status" aria-label="Permalink to &quot;Does Forecast mode affect real Feature status?&quot;">​</a></h3><p>No. Forecast mode is completely separate from actual status. Moving a Feature card in Forecast mode does not update the Feature&#39;s real status anywhere. Forecast positions are saved separately and persist until manually cleared.</p><h3 id="are-forecast-changes-saved-when-i-toggle-back-to-actual" tabindex="-1">Are Forecast changes saved when I toggle back to Actual? <a class="header-anchor" href="#are-forecast-changes-saved-when-i-toggle-back-to-actual" aria-label="Permalink to &quot;Are Forecast changes saved when I toggle back to Actual?&quot;">​</a></h3><p>Yes. Forecast positions are saved separately and persist between sessions. When you toggle back to Forecast, your last forecast positions are restored — you don&#39;t need to rebuild them each time.</p><h3 id="can-both-actual-and-forecast-views-be-exported" tabindex="-1">Can both Actual and Forecast views be exported? <a class="header-anchor" href="#can-both-actual-and-forecast-views-be-exported" aria-label="Permalink to &quot;Can both Actual and Forecast views be exported?&quot;">​</a></h3><p>Yes. Export whichever view is currently active — make sure you&#39;re in the correct mode before exporting. A common practice is to export both and share them side by side to show current state and projected state.</p><h3 id="do-release-ppt-exports-include-ai-generated-content" tabindex="-1">Do Release PPT exports include AI-generated content? <a class="header-anchor" href="#do-release-ppt-exports-include-ai-generated-content" aria-label="Permalink to &quot;Do Release PPT exports include AI-generated content?&quot;">​</a></h3><p>No. Release exports — PNG, PPT, and HTML — are clean visuals of the board with no AI-generated text or speaker notes. What you see on the board is what you get in the export.</p><h3 id="can-release-notes-be-exported" tabindex="-1">Can Release Notes be exported? <a class="header-anchor" href="#can-release-notes-be-exported" aria-label="Permalink to &quot;Can Release Notes be exported?&quot;">​</a></h3><p>Yes. Release Notes can be exported as a PDF, in addition to being copied as plain text.</p><h3 id="can-i-generate-release-notes-more-than-once" tabindex="-1">Can I generate Release Notes more than once? <a class="header-anchor" href="#can-i-generate-release-notes-more-than-once" aria-label="Permalink to &quot;Can I generate Release Notes more than once?&quot;">​</a></h3><p>Yes. Release Notes can be regenerated at any time. However, regenerating overwrites the previous version — there is no version history. If you&#39;ve edited the AI output and want to preserve those edits, copy or export the notes before regenerating.</p><h3 id="can-a-single-release-have-release-notes-for-different-audiences" tabindex="-1">Can a single Release have Release Notes for different audiences? <a class="header-anchor" href="#can-a-single-release-have-release-notes-for-different-audiences" aria-label="Permalink to &quot;Can a single Release have Release Notes for different audiences?&quot;">​</a></h3><p>Yes. Generate internal notes, export or copy them, then generate again with the External audience setting. Each generation overwrites the last, so complete and save one version before switching audiences.</p><h3 id="what-happens-to-features-when-i-archive-a-release" tabindex="-1">What happens to Features when I archive a Release? <a class="header-anchor" href="#what-happens-to-features-when-i-archive-a-release" aria-label="Permalink to &quot;What happens to Features when I archive a Release?&quot;">​</a></h3><p>Nothing. Features are unaffected by archiving — they remain in the backlog and any other Releases they belong to. Archiving only removes the Release from your active list.</p><hr><h2 id="common-issues" tabindex="-1">Common Issues <a class="header-anchor" href="#common-issues" aria-label="Permalink to &quot;Common Issues&quot;">​</a></h2><h3 id="a-feature-s-status-updated-in-the-release-but-didn-t-update-in-the-backlog" tabindex="-1">A Feature&#39;s status updated in the Release but didn&#39;t update in the backlog <a class="header-anchor" href="#a-feature-s-status-updated-in-the-release-but-didn-t-update-in-the-backlog" aria-label="Permalink to &quot;A Feature&#39;s status updated in the Release but didn&#39;t update in the backlog&quot;">​</a></h3><p>This shouldn&#39;t happen — status is a single source of truth and updates everywhere simultaneously. If you&#39;re seeing a discrepancy, try refreshing the page. If the issue persists, check whether the JIRA integration is creating a conflict with the status mapping.</p><h3 id="a-feature-s-status-updated-in-jira-but-isn-t-showing-on-the-release-board" tabindex="-1">A Feature&#39;s status updated in JIRA but isn&#39;t showing on the Release board <a class="header-anchor" href="#a-feature-s-status-updated-in-jira-but-isn-t-showing-on-the-release-board" aria-label="Permalink to &quot;A Feature&#39;s status updated in JIRA but isn&#39;t showing on the Release board&quot;">​</a></h3><p>This is usually a status mapping issue. Check Settings &gt; Integrations &gt; JIRA and review the status mapping configuration — the JIRA status may not be mapped to a Lodestone status stage. Also check whether automatic sync or webhooks are enabled; if only manual sync is configured, you may need to trigger a sync manually.</p><h3 id="my-forecast-positions-disappeared" tabindex="-1">My Forecast positions disappeared <a class="header-anchor" href="#my-forecast-positions-disappeared" aria-label="Permalink to &quot;My Forecast positions disappeared&quot;">​</a></h3><p>Forecast positions persist between sessions but can be manually cleared. Check whether someone on your team cleared the forecast. If positions are missing after a session, also check whether you were in Actual mode when you last left the page — the positions are still there, just hidden until you toggle back to Forecast.</p><h3 id="the-release-notes-don-t-reflect-the-audience-i-selected" tabindex="-1">The Release Notes don&#39;t reflect the audience I selected <a class="header-anchor" href="#the-release-notes-don-t-reflect-the-audience-i-selected" aria-label="Permalink to &quot;The Release Notes don&#39;t reflect the audience I selected&quot;">​</a></h3><p>Regenerating with the correct audience setting selected should fix this. Double-check the audience toggle before generating — Internal and External produce meaningfully different language and framing.</p><h3 id="i-can-t-find-a-release-i-previously-created" tabindex="-1">I can&#39;t find a Release I previously created <a class="header-anchor" href="#i-can-t-find-a-release-i-previously-created" aria-label="Permalink to &quot;I can&#39;t find a Release I previously created&quot;">​</a></h3><p>Check whether the Release has been archived. Archived Releases are removed from the active list but are preserved and accessible from the archived section.</p><h3 id="the-release-board-is-showing-outdated-status-for-features-synced-from-jira" tabindex="-1">The Release board is showing outdated status for Features synced from JIRA <a class="header-anchor" href="#the-release-board-is-showing-outdated-status-for-features-synced-from-jira" aria-label="Permalink to &quot;The Release board is showing outdated status for Features synced from JIRA&quot;">​</a></h3><p>Check your JIRA sync configuration in Settings &gt; Integrations. If automatic sync is enabled, confirm the polling interval and wait for the next sync cycle. If webhooks are configured, check that they&#39;re still active. As a quick fix, trigger a manual sync from the integration settings.</p><hr><p><em>This is version 1 of the Releases documentation, based on the Lodestone knowledge base from early 2025, updated with confirmed platform behavior.</em></p>',46)])])}const f=a(o,[["render",n]]);export{p as __pageData,f as default};
